  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import { useFavorites } from "./hooks/useFavorites";
  7 | import { useHistory } from "./hooks/useHistory";
  8 | import { usePlaylists } from "./hooks/usePlaylists";
  9 | import { useTheme } from "./hooks/useTheme";
 10 | import {
 11 |   TitleBar,
 12 |   Playlist,
 13 |   PlayerControls,
 14 |   ProgressBar,
 15 |   StatusBar,
 16 |   DriveBrowser,
 17 |   AudioVisualizer,
 18 |   HistoryPanel,
 19 |   PlaylistManager,
 20 | } from "./components";
 21 | import type { Track } from "./types";
 22 | 
 23 | function App() {
 24 |   const {
 25 |     state,
 26 |     play,
 27 |     pause,
 28 |     next,
 29 |     prev,
 30 |     seek,
 31 |     setVolume,
 32 |     addTrack,
 33 |     toggleShuffle,
 34 |     reorderPlaylist,
 35 |     toggleFavorite,
 36 |     loadFavorites: loadPlayerFavorites,
 37 |     audioRef,
 38 |   } = usePlayerWithAudio([]);
 39 | 
 40 |   const { processFiles } = useMetadata();
 41 |   const {
 42 |     state: tauriState,
 43 |     openFilePicker,
 44 |     filePathToUrl,
 45 |     sendNotification,
 46 |     registerShortcuts,
 47 |   } = useTauri();
 48 | 
 49 |   const { loadFavorites } = useFavorites();
 50 |   const history = useHistory();
 51 |   const playlists = usePlaylists();
 52 |   const { theme, cycleTheme } = useTheme();
 53 | 
 54 |   const [isLoading, setIsLoading] = useState(false);
 55 |   const [showDrive, setShowDrive] = useState(false);
 56 |   const [showHistory, setShowHistory] = useState(false);
 57 |   const [showPlaylistManager, setShowPlaylistManager] = useState(false);
 58 |   const [isCompact, setIsCompact] = useState(false);
 59 | 
 60 |   const fileInputRef = useRef<HTMLInputElement>(null);
 61 | 
 62 |   // Carrega favoritos salvos ao iniciar
 63 |   useEffect(() => {
 64 |     const savedFavorites = loadFavorites();
 65 |     if (savedFavorites.length > 0) {
 66 |       loadPlayerFavorites(savedFavorites);
 67 |     }
 68 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 69 |   }, []);
 70 | 
 71 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 72 |   useEffect(() => {
 73 |     const cleanup = registerShortcuts({
 74 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 75 |       MediaNextTrack: () => next(),
 76 |       MediaPrevTrack: () => prev(),
 77 |       MediaStop: () => pause(),
 78 |     });
 79 | 
 80 |     return () => {
 81 |       cleanup.then((fn) => fn());
 82 |     };
 83 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 84 | 
 85 |   // Media Session API (navegador)
 86 |   useEffect(() => {
 87 |     if (!("mediaSession" in navigator)) return;
 88 | 
 89 |     navigator.mediaSession.metadata = new MediaMetadata({
 90 |       title: state.currentTrack?.title ?? "Llama Player",
 91 |       artist: state.currentTrack?.artist ?? undefined,
 92 |       album: state.currentTrack?.album ?? undefined,
 93 |     });
 94 | 
 95 |     navigator.mediaSession.setActionHandler("play", () => play());
 96 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 97 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 98 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 99 |   }, [state.currentTrack, play, pause, next, prev]);
100 | 
101 |   // Notificação ao trocar de música + histórico
102 |   useEffect(() => {
103 |     if (state.currentTrack && state.isPlaying) {
104 |       sendNotification(
105 |         `▶ ${state.currentTrack.title}`,
106 |         state.currentTrack.artist
107 |           ? `Por ${state.currentTrack.artist}`
108 |           : undefined
109 |       );
110 |       history.addEntry(state.currentTrack);
111 |     }
112 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
113 | 
114 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
115 | 
116 |   const handleSelectTrack = (track: Track) => {
117 |     play(track);
118 |   };
119 | 
120 |   const handleOpenFile = async () => {
121 |     if (tauriState.isTauri) {
122 |       // Usa file picker nativo do Tauri
123 |       setIsLoading(true);
124 |       try {
125 |         const paths = await openFilePicker();
126 |         if (!paths || paths.length === 0) return;
127 | 
128 |         // Converte paths para File objects (via fetch do asset protocol)
129 |         const tracks: Track[] = [];
130 |         for (const path of paths) {
131 |           const url = await filePathToUrl(path);
132 |           const name = path.split(/[/\\]/).pop() || path;
133 |           tracks.push({
134 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
135 |             title: name.replace(/\.[^/.]+$/, ""),
136 |             duration: 0,
137 |             src: url,
138 |           });
139 |         }
140 | 
141 |         for (const track of tracks) {
142 |           addTrack(track);
143 |         }
144 | 
145 |         if (!state.currentTrack && tracks.length > 0) {
146 |           play(tracks[0]);
147 |         }
148 |       } catch (err) {
149 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
150 |       } finally {
151 |         setIsLoading(false);
152 |       }
153 |     } else {
154 |       // Fallback: input file HTML
155 |       fileInputRef.current?.click();
156 |     }
157 |   };
158 | 
159 |   const handleFileChange = useCallback(
160 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
161 |       const files = e.target.files;
162 |       if (!files || files.length === 0) return;
163 | 
164 |       setIsLoading(true);
165 | 
166 |       try {
167 |         const fileArray = Array.from(files);
168 |         const tracks = await processFiles(fileArray);
169 | 
170 |         for (const track of tracks) {
171 |           addTrack(track);
172 |         }
173 | 
174 |         // If nothing is playing, start with the first track
175 |         if (!state.currentTrack && tracks.length > 0) {
176 |           play(tracks[0]);
177 |         }
178 |       } catch (err) {
179 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
180 |       } finally {
181 |         setIsLoading(false);
182 |       }
183 | 
184 |       // Reset input so the same file can be selected again
185 |       e.target.value = "";
186 |     },
187 |     [processFiles, addTrack, state.currentTrack, play]
188 |   );
189 | 
190 |   const handleDropFiles = useCallback(
191 |     async (files: FileList) => {
192 |       setIsLoading(true);
193 |       try {
194 |         const fileArray = Array.from(files);
195 |         const tracks = await processFiles(fileArray);
196 |         for (const track of tracks) {
197 |           addTrack(track);
198 |         }
199 |         if (!state.currentTrack && tracks.length > 0) {
200 |           play(tracks[0]);
201 |         }
202 |       } catch (err) {
203 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
204 |       } finally {
205 |         setIsLoading(false);
206 |       }
207 |     },
208 |     [processFiles, addTrack, state.currentTrack, play]
209 |   );
210 | 
211 |   const handleAddDriveTracks = useCallback(
212 |     (tracks: Track[]) => {
213 |       for (const track of tracks) {
214 |         addTrack(track);
215 |       }
216 |       if (!state.currentTrack && tracks.length > 0) {
217 |         play(tracks[0]);
218 |       }
219 |     },
220 |     [addTrack, state.currentTrack, play]
221 |   );
222 | 
223 |   return (
224 |     <div className="app">
225 |       <TitleBar />
226 | 
227 |       <main className="main-content">
228 |         <div className="toolbar">
229 |           <button
230 |             className="toolbar-btn"
231 |             onClick={handleOpenFile}
232 |             disabled={isLoading}
233 |             title="Abrir arquivo de áudio local"
234 |           >
235 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
236 |           </button>
237 |           <input
238 |             ref={fileInputRef}
239 |             type="file"
240 |             accept="audio/*"
241 |             multiple
242 |             style={{ display: "none" }}
243 |             onChange={handleFileChange}
244 |           />
245 |           <button
246 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
247 |             onClick={() => setShowDrive((v) => !v)}
248 |             title="Google Drive"
249 |           >
250 |             ☁️ Drive
251 |           </button>
252 |           <button
253 |             className={`toolbar-btn ${showHistory ? "toolbar-btn-active" : ""}`}
254 |             onClick={() => setShowHistory((v) => !v)}
255 |             title="Histórico de reprodução"
256 |           >
257 |             🕐 Histórico
258 |           </button>
259 |           <button
260 |             className={`toolbar-btn ${showPlaylistManager ? "toolbar-btn-active" : ""}`}
261 |             onClick={() => setShowPlaylistManager((v) => !v)}
262 |             title="Gerenciar playlists"
263 |           >
264 |             📋 Playlists
265 |           </button>
266 |           <button
267 |             className="toolbar-btn"
268 |             onClick={cycleTheme}
269 |             title={`Tema: ${theme === "winamp" ? "Winamp Nostálgico" : theme === "dark" ? "Escuro" : "Claro"}`}
270 |           >
271 |             {theme === "winamp" ? "🎨" : theme === "dark" ? "🌙" : "☀️"}
272 |           </button>
273 |         </div>
274 | 
275 |         {showDrive && (
276 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
277 |         )}
278 | 
279 |         {showHistory && (
280 |           <HistoryPanel
281 |             entries={history.entries}
282 |             onSelectTrack={handleSelectTrack}
283 |             onClear={history.clear}
284 |           />
285 |         )}
286 | 
287 |         {showPlaylistManager && (
288 |           <PlaylistManager
289 |             playlists={playlists.playlists}
290 |             activePlaylistId={playlists.activePlaylistId}
291 |             currentTracks={state.playlist}
292 |             onSavePlaylist={playlists.saveCurrentPlaylist}
293 |             onLoadPlaylist={playlists.loadPlaylist}
294 |             onDeletePlaylist={playlists.deletePlaylist}
295 |             onRenamePlaylist={playlists.renamePlaylist}
296 |             onReplaceTracks={(tracks) => {
297 |               // Replace entire playlist
298 |               // First clear by reordering to empty, then add tracks
299 |               // We use a workaround: reorder to empty then add each track
300 |               // Actually, let's just load the tracks into the playlist
301 |               // by reordering to the saved tracks
302 |               if (tracks.length === 0) return;
303 |               // We need to replace the playlist. Since we have reorderPlaylist,
304 |               // we can set the playlist to the loaded tracks directly.
305 |               // The cleanest approach: reorder to the loaded tracks.
306 |               reorderPlaylist(tracks);
307 |               // Start playing the first track
308 |               play(tracks[0]);
309 |             }}
310 |             onClose={() => setShowPlaylistManager(false)}
311 |           />
312 |         )}
313 | 
314 |         <Playlist
315 |           tracks={state.playlist}
316 |           currentTrackId={state.currentTrack?.id ?? null}
317 |           isPlaying={state.isPlaying}
318 |           onSelectTrack={handleSelectTrack}
319 |           onReorderPlaylist={reorderPlaylist}
320 |           onDropFiles={handleDropFiles}
321 |           onToggleFavorite={toggleFavorite}
322 |         />
323 | 
324 |         <PlayerControls
325 |           currentTrack={state.currentTrack}
326 |           currentTrackId={state.currentTrack?.id ?? null}
327 |           isPlaying={state.isPlaying}
328 |           isShuffled={state.isShuffled}
329 |           isCompact={isCompact}
330 |           onPlay={() => play()}
331 |           onPause={pause}
332 |           onNext={next}
333 |           onPrev={prev}
334 |           onToggleShuffle={toggleShuffle}
335 |           onToggleFavorite={toggleFavorite}
336 |           onToggleCompact={() => setIsCompact((v) => !v)}
337 |         />
338 | 
339 |         <AudioVisualizer
340 |           frequencyData={visualizer.frequencyData}
341 |           waveformData={visualizer.waveformData}
342 |           isActive={visualizer.isActive}
343 |         />
344 | 
345 |         <ProgressBar
346 |           currentTime={state.currentTime}
347 |           duration={state.duration}
348 |           onSeek={seek}
349 |         />
350 |       </main>
351 | 
352 |       <StatusBar
353 |         isPlaying={state.isPlaying}
354 |         volume={state.volume}
355 |         onVolumeChange={setVolume}
356 |       />
357 |     </div>
358 |   );
359 | }
360 | 
361 | export default App;
